-- Frozen v1 workflow: all domain writes pass checked transactional functions.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id), display_name text not null default '');
create table public.projects (id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name))>0), description text, created_by uuid not null references auth.users(id), archived_at timestamptz, row_version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.project_members (project_id uuid not null references public.projects(id), user_id uuid not null references auth.users(id), role text not null check(role in ('owner','editor','viewer')), primary key(project_id,user_id));
create function public.gs_role(p_project uuid) returns text language sql stable security definer set search_path=public,pg_temp as $$ select role from project_members where project_id=p_project and user_id=auth.uid() $$;
create function public.gs_require(p_project uuid,p_owner boolean default false) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin
 if auth.uid() is null or coalesce(gs_role(p_project),'') not in ('owner','editor') or (p_owner and gs_role(p_project)<>'owner') then raise exception 'UNAUTHORIZED'; end if;
 if exists(select 1 from projects where id=p_project and archived_at is not null) then raise exception 'PROJECT_ARCHIVED'; end if;
end $$;
create table public.documents (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), title text not null default '', type text not null default 'OTHER' check(type in ('TOR','BOQ','SPEC','OTHER')), current_version_id uuid, retired_at timestamptz, row_version integer not null default 1, created_at timestamptz not null default now(), unique(id,project_id));
create table public.document_versions (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), document_id uuid not null, version_no integer not null default 1, filename text not null, storage_path text not null unique, checksum text, bytes bigint check(bytes>0 and bytes<=26214400), mime text not null, upload_state text not null default 'UPLOADING' check(upload_state in ('UPLOADING','READY','FAILED')), provenance text not null default 'uploaded' check(provenance in ('uploaded','fixture','generated')), fixture_id text, extraction jsonb not null default '[]', failure_reason text, row_version integer not null default 1, created_at timestamptz not null default now(), unique(document_id,version_no), unique(id,project_id), foreign key(document_id,project_id) references public.documents(id,project_id));
alter table public.documents add constraint documents_current_version_fk foreign key(current_version_id,project_id) references public.document_versions(id,project_id);
create table public.analysis_runs (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), parent_run_id uuid, input_snapshot jsonb not null, input_fingerprint text not null, mode text not null default 'simulated' check(mode='simulated'), scenario text not null, status text not null default 'QUEUED' check(status in ('QUEUED','PROCESSING','COMPLETED','PARTIAL','FAILED')), request_id text not null, review_epoch integer not null default 1, result jsonb, errors jsonb not null default '[]', warnings jsonb not null default '[]', finalized boolean not null default false, stale boolean not null default false, heartbeat_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(project_id,request_id), unique(id,project_id), foreign key(parent_run_id,project_id) references public.analysis_runs(id,project_id));
create table public.analysis_inputs (project_id uuid not null, run_id uuid not null, document_version_id uuid not null, primary key(run_id,document_version_id), foreign key(run_id,project_id) references public.analysis_runs(id,project_id), foreign key(document_version_id,project_id) references public.document_versions(id,project_id));
create table public.recommendations (id uuid primary key default gen_random_uuid(), project_id uuid not null, run_id uuid not null, lineage_id text not null, work_scope_key text not null, payload jsonb not null, unique(id,project_id), foreign key(run_id,project_id) references public.analysis_runs(id,project_id));
create table public.source_references (id uuid primary key default gen_random_uuid(), project_id uuid not null, recommendation_id uuid not null, document_version_id uuid not null, exact_text text not null, locator jsonb not null, foreign key(recommendation_id,project_id) references public.recommendations(id,project_id), foreign key(document_version_id,project_id) references public.document_versions(id,project_id));
create table public.reviews (id uuid primary key default gen_random_uuid(), project_id uuid not null, recommendation_id uuid not null unique, decision text not null default 'UNREVIEWED' check(decision in ('UNREVIEWED','APPROVED','REJECTED')), reason text not null default '', reviewer_id uuid references auth.users(id), locked boolean not null default false, row_version integer not null default 1, unique(id,project_id), foreign key(recommendation_id,project_id) references public.recommendations(id,project_id));
create table public.feedback (id uuid primary key default gen_random_uuid(), project_id uuid not null, run_id uuid not null, recommendation_id uuid, text text not null check(length(trim(text))>0), author_id uuid not null references auth.users(id), row_version integer not null default 1, created_at timestamptz not null default now(), foreign key(run_id,project_id) references public.analysis_runs(id,project_id), foreign key(recommendation_id,project_id) references public.recommendations(id,project_id));
create table public.decision_sets (id uuid primary key default gen_random_uuid(), project_id uuid not null, run_id uuid not null, version_no integer not null, finalized_by uuid not null references auth.users(id), finalized_at timestamptz not null default now(), summary_snapshot jsonb not null, unique(project_id,version_no), unique(id,project_id), foreign key(run_id,project_id) references public.analysis_runs(id,project_id));
create table public.decision_items (id uuid primary key default gen_random_uuid(), project_id uuid not null, decision_set_id uuid not null, recommendation_id uuid not null, decision text not null check(decision in ('APPROVED','REJECTED')), snapshot jsonb not null, lineage_id text not null, work_scope_key text not null, unique(decision_set_id,recommendation_id), unique(id,project_id), foreign key(decision_set_id,project_id) references public.decision_sets(id,project_id), foreign key(recommendation_id,project_id) references public.recommendations(id,project_id));
create table public.packages (id uuid primary key default gen_random_uuid(), project_id uuid not null, origin_decision_item_id uuid not null unique, lineage_id text not null, scope_key text not null, snapshot jsonb not null, owner_id uuid references auth.users(id), execution_status text not null default 'APPROVED', verification_status text not null default 'PENDING', superseded_at timestamptz, row_version integer not null default 1, created_at timestamptz not null default now(), unique(id,project_id), foreign key(origin_decision_item_id,project_id) references public.decision_items(id,project_id));
create unique index packages_active_scope on public.packages(project_id,scope_key) where superseded_at is null;
create table public.tasks (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null, title text not null check(length(trim(title))>0), assignee_id uuid references auth.users(id), due_at timestamptz, completed_at timestamptz, status text not null default 'TODO' check(status in ('TODO','IN_PROGRESS','DONE')), priority text not null default 'normal', row_version integer not null default 1, unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id));
create table public.milestones (like public.tasks including all);
alter table public.milestones add foreign key(package_id,project_id) references public.packages(id,project_id);
create table public.procurements (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null unique, supplier_name text, po_reference text, ordered_qty numeric check(ordered_qty>0), unit text, variance_reason text, expected_delivery_at timestamptz, accepted_at timestamptz, accepted_by uuid references auth.users(id), status text not null default 'APPROVED' check(status in ('APPROVED','RFQ','SUPPLIER_SELECTED','PO_ISSUED','SHIPPING','DELIVERED','ACCEPTED')), row_version integer not null default 1, unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id));
create table public.implementation_entries (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null, kind text not null check(kind in ('delivery','install')), quantity numeric not null check(quantity>=0), unit text not null, occurred_at timestamptz not null default now(), actor_id uuid not null references auth.users(id), notes text not null default '', corrects_id uuid references public.implementation_entries(id), row_version integer not null default 1, unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id));
create unique index one_implementation_correction on public.implementation_entries(corrects_id) where corrects_id is not null;
create table public.issues (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null, title text not null check(length(trim(title))>0), description text not null default '', severity text not null default 'normal' check(severity in ('normal','high','critical')), blocks_verification boolean not null default false, owner_id uuid references auth.users(id), status text not null default 'OPEN' check(status in ('OPEN','IN_PROGRESS','RESOLVED')), resolution text, requires_feature1_review boolean not null default false, row_version integer not null default 1, created_at timestamptz not null default now(), unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id));
create table public.evidence_files (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null, storage_path text not null unique, filename text not null, mime text not null, kind text not null, upload_state text not null default 'UPLOADING' check(upload_state in ('UPLOADING','READY','FAILED')), checksum text, provenance text not null default 'recorded' check(provenance in ('simulated','recorded')), uploaded_by uuid not null references auth.users(id), row_version integer not null default 1, unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id));
create table public.verifications (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null, result text not null check(result in ('PENDING','PASS','NON_CONFORMANCE')), verifier_id uuid not null references auth.users(id), notes text not null check(length(trim(notes))>0), provenance text not null, verified_at timestamptz not null default now(), unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id));
create table public.verification_evidence (project_id uuid not null, verification_id uuid not null, evidence_id uuid not null, primary key(verification_id,evidence_id), foreign key(verification_id,project_id) references public.verifications(id,project_id), foreign key(evidence_id,project_id) references public.evidence_files(id,project_id));
create table public.actual_results (id uuid primary key default gen_random_uuid(), project_id uuid not null, package_id uuid not null, metric text not null check(metric in ('cost','carbon')), total_value numeric check(total_value>=0), unit text not null check(unit in ('THB','tCO2e')), source_description text not null, methodology text not null, provenance text not null default 'recorded' check(provenance in ('simulated','recorded')), evidence_id uuid, recorded_by uuid not null references auth.users(id), row_version integer not null default 1, unique(package_id,metric), unique(id,project_id), foreign key(package_id,project_id) references public.packages(id,project_id), foreign key(evidence_id,project_id) references public.evidence_files(id,project_id), check((metric='cost' and unit='THB') or (metric='carbon' and unit='tCO2e')));
create table public.comments (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), target_kind text not null, target_id uuid not null, actor_id uuid not null references auth.users(id), text text not null check(length(trim(text))>0), row_version integer not null default 1, created_at timestamptz not null default now());
create table public.activity_events (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), target_kind text not null, target_id uuid not null, actor_id uuid references auth.users(id), event text not null, before jsonb, after jsonb, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), recipient_id uuid not null references auth.users(id), kind text not null, target_id uuid not null, dedup_key text not null, read_at timestamptz, created_at timestamptz not null default now(), unique(recipient_id,dedup_key));
create table public.document_revisions (id uuid primary key default gen_random_uuid(), project_id uuid not null, decision_set_id uuid not null, request_id text not null, source_version_id uuid, output_version_id uuid, output_path text, status text not null default 'REQUESTED', mode text not null default 'simulated', changes jsonb not null default '[]', unapplied jsonb not null default '[]', exclusions jsonb not null default '[]', outdated boolean not null default false, approved_by uuid references auth.users(id), approved_at timestamptz, row_version integer not null default 1, created_at timestamptz not null default now(), unique(project_id,request_id,source_version_id), unique(id,project_id), foreign key(decision_set_id,project_id) references public.decision_sets(id,project_id), foreign key(source_version_id,project_id) references public.document_versions(id,project_id), foreign key(output_version_id,project_id) references public.document_versions(id,project_id));
create table public.operation_receipts (project_id uuid not null references public.projects(id), request_id text not null, operation text not null, actor_id uuid not null references auth.users(id), result jsonb not null, primary key(project_id,operation,request_id));
create function public.gs_log(p_project uuid,p_kind text,p_id uuid,p_event text,p_before jsonb,p_after jsonb) returns void language sql security definer set search_path=public,pg_temp as $$ insert into activity_events(project_id,target_kind,target_id,actor_id,event,before,after) values(p_project,p_kind,p_id,auth.uid(),p_event,p_before,p_after) $$;
create function public.gs_immutable() returns trigger language plpgsql as $$ begin raise exception 'IMMUTABLE_SNAPSHOT'; end $$;
create trigger decisions_immutable before update or delete on public.decision_sets for each row execute function public.gs_immutable();
create trigger items_immutable before update or delete on public.decision_items for each row execute function public.gs_immutable();
create trigger events_immutable before update or delete on public.activity_events for each row execute function public.gs_immutable();
create trigger recommendations_immutable before update or delete on public.recommendations for each row execute function public.gs_immutable();
create function public.gs_ready_version_immutable() returns trigger language plpgsql as $$ begin if old.upload_state='READY' then raise exception 'IMMUTABLE_SOURCE'; end if; return new; end $$;
create trigger version_immutable before update or delete on public.document_versions for each row execute function public.gs_ready_version_immutable();
do $$ declare t text; begin foreach t in array array['projects','project_members','documents','document_versions','analysis_runs','analysis_inputs','recommendations','source_references','reviews','feedback','decision_sets','decision_items','packages','tasks','milestones','procurements','implementation_entries','issues','evidence_files','verifications','verification_evidence','actual_results','comments','activity_events','notifications','document_revisions','operation_receipts'] loop
 execute format('alter table public.%I enable row level security',t);
 if t='projects' then execute 'create policy member_read on public.projects for select to authenticated using (gs_role(id) is not null)';
 elsif t='notifications' then execute 'create policy member_read on public.notifications for select to authenticated using (recipient_id=auth.uid() and gs_role(project_id) is not null)';
 else execute format('create policy member_read on public.%I for select to authenticated using (gs_role(project_id) is not null)',t); end if;
 execute format('grant select on public.%I to authenticated',t);
 execute format('revoke insert,update,delete on public.%I from authenticated,anon',t);
end loop; end $$;
alter table public.profiles enable row level security;
create policy profile_self on public.profiles for select to authenticated using(id=auth.uid());
grant select on public.profiles to authenticated;
-- Helpers are private; exposed operations explicitly granted in later migration.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.gs_role(uuid) to authenticated;

